def base_to_int(s, base):
    if not 2 <= base <= 36:
        raise ValueError("base must be between 2 and 36")
    if not s:
        raise ValueError("empty string is not a valid number")
    result = 0
    for ch in s:
        ch = ch.lower()
        if not ('0' <= ch <= '9' or 'a' <= ch <= 'z'):
            raise ValueError(f"invalid character {ch!r} for base {base}")
        digit = ord(ch) - ord('0') if ch.isdigit() else ord(ch) - ord('a') + 10
        if digit >= base:
            raise ValueError(f"invalid digit {ch!r} for base {base}")
        result = result * base + digit
    return result
